    .setTitle('TruckConnect Fleet API')
    .setDescription('Backend REST API for TruckConnect Android Driver and Admin Fleet Platform')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, config);
